//! The Rust distortion port must match Monado's C function. The fixture holds outputs of Monado's
//! own code, generated by tools/port-psvr2-distortion.py.

use halliday_core::psvr2::distortion::{Eye, compute};

const FIXTURE: &str = include_str!("fixtures/psvr2_distortion_reference.txt");

const CALIBRATIONS: [[f32; 8]; 2] = [
    [-0.099_192_93, 0.0, 0.099_192_93, 0.0, 1.0, 0.0, 1.0, 0.0],
    [
        -0.0987, 0.0006, 0.0994, -0.0003, 0.99998, -0.0061, 0.99999, 0.0043,
    ],
];

#[test]
fn matches_monado_reference() {
    let mut checked = 0;
    let mut max_err = 0f32;
    for line in FIXTURE
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
    {
        let f: Vec<&str> = line.split_whitespace().collect();
        let cal: usize = f[0].parse().unwrap();
        let eye = if f[1] == "0" { Eye::Left } else { Eye::Right };
        let n: Vec<f32> = f[2..].iter().map(|s| s.parse().unwrap()).collect();
        let t = compute(&CALIBRATIONS[cal], eye, n[0], n[1]);
        let got = [t.r[0], t.r[1], t.g[0], t.g[1], t.b[0], t.b[1]];
        for (g, want) in got.iter().zip(&n[2..]) {
            // %.9g round-trips f32 exactly; allow a couple of ulps for libm/fma differences.
            let err = (g - want).abs() / want.abs().max(1.0);
            max_err = max_err.max(err);
            assert!(err < 1e-6, "{line}: got {got:?}");
        }
        checked += 1;
    }
    assert_eq!(checked, 2 * 2 * 17 * 17);
    eprintln!("max relative error vs Monado: {max_err:e}");
}
